import json
# build f: bg = most common; find hollow-rectangle frame of second color (the one forming a rectangle outline); pattern = 8-conn non-bg component adjacent to frame bbox; output = pattern placed in interior of rectangle with ring of frame color.
def f(I):
    from collections import Counter
    H,W=len(I),len(I[0])
    bg=Counter(x for r in I for x in r).most_common(1)[0][0]
    seen=[[False]*W for _ in range(H)]
    best=None
    for i in range(H):
        for j in range(W):
            if I[i][j]!=bg and not seen[i][j]:
                st=[(i,j)]; seen[i][j]=True; comp=[]
                while st:
                    r,c=st.pop(); comp.append((r,c))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            nr,nc=r+dr,c+dc
                            if 0<=nr<H and 0<=nc<W and not seen[nr][nc] and I[nr][nc]==I[i][j]:
                                seen[nr][nc]=True; st.append((nr,nc))
                rs=[a for a,b in comp]; cs=[b for a,b in comp]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                ok=all(I[a][b]==I[i][j] for a,b in comp)\
                   and all(I[a][b]==bg for a in range(r0,r1+1) for b in range(c0,c1+1)
                         if not(a in(r0,r1) or b in(c0,c1)))
                if ok and (best is None or len(comp)>best[0]):
                    best=(len(comp),(I[i][j],r0,r1,c0,c1))
    _,(fc,r0,r1,c0,c1)=best
    F,H2,W2=len(I),len(I[0])
    # pattern = non-bg cells outside rect bbox that touch it (4-conn flood)
    outside=set()
    for i in range(F):
        for j in range(W2):
            if I[i][j]!=bg and not(r0<=i<=r1 and c0<=j<=c1):
                near=any(max(abs(i-a),abs(j-b))==1 and r0<=a<=r1 and c0<=b<=c1
                        for a in range(F) for b in range(W2) if I[a][b]==I[i][j] and True)
                outside.add((i,j))
    pat=set(outside)
    st=list(outside)
    while st:
        i,j=st.pop()
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<F and 0<=nj<W2 and (ni,nj) not in pat and I[ni][nj]!=bg:
                pat.add((ni,nj)); st.append((ni,nj))
    prs=[a for a,b in pat]; pcs=[b for a,b in pat]
    ptop,pbot,pleft,pright=min(prs),max(prs),min(pcs),max(pcs)
    ph,pw=pbot-ptop+1,pright-pleft+1
    out=[[fc]*(pw+2) for _ in range(ph+2)]
    for a in range(ptop,pbot+1):
        for b in range(pleft,pright+1):
            v=I[a][b]
            if v!=bg: out[a-ptop][b-pleft]=v
    return out
